import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def count_divisors_of_x_squared(x):
    if x == 1:
        return 1 # d(1^2) = 1

    factors_x = prime_factorization(x)

    # If x = p1^a1 * p2^a2 * ..., then x^2 = p1^(2a1) * p2^(2a2) * ...
    # d(x^2) = (2a1 + 1) * (2a2 + 1) * ...

    d_x2 = 1
    for prime, exponent in factors_x.items():
        d_x2 *= (2 * exponent + 1)
    return d_x2

def calculate_f_x(x):
    d_x2 = count_divisors_of_x_squared(x)
    # f(x) = (d(x^2) - 1) / 2
    return (d_x2 - 1) // 2

# Calculate f(x) for x=1 to 50
results = {}
for x in range(1, 51):
    f_x = calculate_f_x(x)
    results[x] = f_x

